static void ae350_do_nmi_on_cpu(CPUState *cs, run_on_cpu_data arg)
{
    RISCVCPU *cpu = RISCV_CPU(cs);
    CPURISCVState *env = &cpu->env;
    env->mcause = 0x1;
    env->mepc = env->pc;
    env->pc = env->resetvec;
}

static void ae350_nmi(NMIState *n, int cpu_index, Error **errp)
{
    CPUState *cs = qemu_get_cpu(cpu_index);
    async_run_on_cpu(cs, ae350_do_nmi_on_cpu, RUN_ON_CPU_NULL);
}

static void andes_ae350_machine_class_init(ObjectClass *oc, const void *data)
{
    MachineClass *mc = MACHINE_CLASS(oc);
    NMIClass *nc = NMI_CLASS(oc);
    mc->desc = "RISC-V Board compatible with Andes AE350";
    mc->init = andes_ae350_machine_init;
    mc->max_cpus = ANDES_CPUS_MAX;
    mc->default_cpu_type = VIRT_CPU;
    mc->default_ram_id = "riscv.andes.ae350.ram";
    mc->possible_cpu_arch_ids = riscv_numa_possible_cpu_arch_ids;
    mc->cpu_index_to_instance_props = riscv_numa_cpu_index_to_props;
    mc->get_default_cpu_node_id = riscv_numa_get_default_cpu_node_id;
    mc->numa_mem_supported = false;
    object_class_property_add_str(oc, "aia", andes_ae350_get_aia,
                                  andes_ae350_set_aia);
    object_class_property_set_description(oc, "aia",
                                          "Set type of AIA interrupt "
                                          "controller. Valid values are "
                                          "none, aplic, and aplic-imsic.");

    object_class_property_add_str(oc, "aia-guests",
                                  andes_ae350_get_aia_guests,
                                  andes_ae350_set_aia_guests);
    {
        g_autofree char *str =

AndesAe350BoardState *bs = ANDES_AE350_MACHINE(machine);
MemoryRegion *system_memory = get_system_memory();
MemoryRegion *mask_nor = g_new(MemoryRegion, 1);
MemoryRegion *mask_hvm = g_new(MemoryRegion, 1);
MemoryRegion *mask_l2c = g_new(MemoryRegion, 1);
MemoryRegion *mask_dtrom = g_new(MemoryRegion, 1);
target_ulong start_addr = memmap[ANDES_AE350_DRAM].base;
target_ulong firmware_end_addr, kernel_start_addr;
uint64_t kernel_entry;
RISCVBootInfo boot_info;

/* Initialize SoC */
object_initialize_child(OBJECT(machine), "soc",
                &bs->soc, TYPE_ANDES_AE350_SOC);
qdev_realize(DEVICE(&bs->soc), NULL, &error_abort);

/* Check ram size is validate */
uint64_t main_size = machine->ram_size;
uint64_t ext_size = 0;

if (main_size > memmap[ANDES_AE350_DRAM].size) {
    ext_size = main_size - memmap[ANDES_AE350_DRAM].size;
    main_size = memmap[ANDES_AE350_DRAM].size;

    if (ext_size > memmap[ANDES_AE350_DRAM_EXT].size) {
        error_report("Cannot model more than %ldGB RAM",
            (long)(memmap[ANDES_AE350_DRAM].size +
                   memmap[ANDES_AE350_DRAM_EXT].size) /
                   (1024 * 1024 * 1024));
        exit(1);
    }
}

/*
 * Register system main memory. machine->ram is the framework-owned
 * backend (mc->default_ram_id, set in class_init): passing
 * -machine andes_ae350,memory-backend=<id> maps it onto a user backend
 * (e.g. memory-backend-file) for the hybrid-sim QEMU<->vsim shared-RAM
 * round-trip; otherwise an anonymous backend is auto-created (identical
 * to the previous init_ram behavior). The single backend spans both DRAM
 * windows through aliases -- its low main_size bytes map to DRAM, the
 * remaining ext_size bytes to DRAM_EXT.
 */
MemoryRegion *main_mem = g_new(MemoryRegion, 1);
memory_region_init_alias(main_mem, NULL, "riscv.andes.ae350.ram.main",
                         machine->ram, 0, main_size);
memory_region_add_subregion(system_memory, memmap[ANDES_AE350_DRAM].base,
                            main_mem);

/* register extended memory if needed (an alias into the same backend) */
if (ext_size > 0) {
    MemoryRegion *ext_mem = g_new(MemoryRegion, 1);
    memory_region_init_alias(ext_mem, NULL, "riscv.andes.ae350.ram.ext",
                             machine->ram, main_size, ext_size);
    memory_region_add_subregion(system_memory,
        memmap[ANDES_AE350_DRAM_EXT].base, ext_mem);
}

/* NOR FLASH */
memory_region_init_rom(mask_nor, NULL, "riscv.andes.ae350.nor",
                       memmap[ANDES_AE350_NOR].size, &error_fatal);
memory_region_add_subregion(system_memory, memmap[ANDES_AE350_NOR].base,
                            mask_nor);

/* SimControl (vplat runtime exit device @ 0xe0080000) */
MemoryRegion *sim_ctrl_mr = g_new(MemoryRegion, 1);
memory_region_init_io(sim_ctrl_mr, NULL, &andesim_ctrl_ops, NULL,
                      "riscv.andes.ae350.sim_ctrl",
                      memmap[ANDES_AE350_SIM_CTRL].size);
memory_region_add_subregion(system_memory,
                            memmap[ANDES_AE350_SIM_CTRL].base,
                            sim_ctrl_mr);

/* HVM */
memory_region_init_ram(mask_hvm, NULL, "riscv.andes.ae350.hvm",
                       1 << bs->soc.hvm_size_pow_2, &error_fatal);
